"""Report generation facade for trade and daily reports."""

from __future__ import annotations

from dataclasses import dataclass
from datetime import date
from pathlib import Path
from typing import Any, Mapping

from reports.daily_report import DailyReportBuilder, DailyReportSummary
from reports.trade_report import TRADE_REPORT_COLUMNS, TradeReportBuilder
from utils.config_loader import ConfigLoader
from utils.file_utils import save_csv, save_excel


@dataclass(frozen=True)
class GeneratedReportPaths:
    """Paths generated by ReportGenerator."""

    trade_excel: Path
    trade_csv: Path
    daily_excel: Path


class ReportGenerator:
    """Generate trade and daily reports."""

    def __init__(
        self,
        *,
        config_loader: ConfigLoader | None = None,
        trade_report_dir: str | Path | None = None,
        daily_report_dir: str | Path | None = None,
    ) -> None:
        """Create report generator."""

        self.config_loader = config_loader or ConfigLoader()
        self.config = self.config_loader.load()
        self.trade_report_dir = Path(trade_report_dir or self.config.settings.report_paths.get("trades", Path("reports/trades")))
        self.daily_report_dir = Path(daily_report_dir or self.config.settings.report_paths.get("daily", Path("reports/daily")))
        self.trade_builder = TradeReportBuilder()
        self.daily_builder = DailyReportBuilder(
            capital=self.config.risk_limits.capital,
            max_daily_loss_percent=self.config.risk_limits.max_daily_loss_percent,
        )

    def generate_trade_report(
        self,
        trades: list[Mapping[str, Any] | Any],
        *,
        report_date: date,
        name: str | None = None,
    ) -> tuple[Path, Path]:
        """Generate trade report Excel and CSV files."""

        rows = self.trade_builder.build_rows(trades)
        stem = name or f"trade_report_{report_date.isoformat()}"
        excel_path = save_excel(rows, self.trade_report_dir / f"{stem}.xlsx", sheet_name="Trades", fieldnames=TRADE_REPORT_COLUMNS)
        csv_path = save_csv(rows, self.trade_report_dir / f"{stem}.csv", fieldnames=TRADE_REPORT_COLUMNS)
        return excel_path, csv_path

    def generate_daily_report(
        self,
        trades: list[Mapping[str, Any] | Any],
        *,
        report_date: date,
        name: str | None = None,
    ) -> tuple[DailyReportSummary, Path]:
        """Generate daily summary report."""

        summary = self.daily_builder.build(trades, report_date=report_date)
        stem = name or f"daily_report_{report_date.isoformat()}"
        path = save_excel([summary.as_dict()], self.daily_report_dir / f"{stem}.xlsx", sheet_name="Daily")
        return summary, path

    def generate_all(
        self,
        trades: list[Mapping[str, Any] | Any],
        *,
        report_date: date,
        name: str | None = None,
    ) -> GeneratedReportPaths:
        """Generate trade and daily reports."""

        trade_excel, trade_csv = self.generate_trade_report(trades, report_date=report_date, name=name)
        _summary, daily_excel = self.generate_daily_report(trades, report_date=report_date, name=name)
        return GeneratedReportPaths(trade_excel=trade_excel, trade_csv=trade_csv, daily_excel=daily_excel)
